SELECT c.code,
 (SELECT count(*) FROM public.cadre_form_fields f WHERE f.cadre_id = c.id)
 + (SELECT count(*) FROM added_fields f WHERE f.cadre_id = c.id)
 AS fields_after_restore
FROM target_cadres c ORDER BY c.code;
